//! 🧪️ The defining empty lanes use genuine canonical Pack receiving and native Store genesis.
use super::*;
use semio_framework_plugin_ownership::original_store_genesis::{OriginalStoreGenesis,OriginalStoreGenesisOwner};
use semio_framework_plugin_decl_views::{NoConfig,NoConfigGenesisOwner,NoDraftGenesisOwner};
fn empty_genesis<O:OriginalStoreGenesisOwner<State=NoConfig,Mutation=semio_framework_plugin_decl_views::NoConfigMutation>>(){
 let law:serde_json::Value=serde_json::from_str(include_str!("genesis.json")).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,maximum_release_bytes:16<<20,maximum_depth:4096};
 for cut in law["cancelAfter"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize).chain([1000000]){
  let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let actor=store::ActorId("empty-lane-reader".into());let mut owner=original_emission_capture_tests::actual_turn(&mut caller,&mut decoder,g,|cx|OriginalStoreGenesis::<O>::admit("energy-empty",&actor,cx));let mut candidate=None;for index in 0..cut{candidate=original_emission_capture_tests::actual_turn(&mut caller,&mut decoder,g,|cx|owner.as_mut().unwrap().step(cx));if candidate.is_some(){break}assert!(index<999999,"empty native genesis stalled {:?}",owner.as_ref().unwrap().progress())}
  if cut==1000000{let(label,store)=candidate.as_ref().expect("actual empty lane Store");assert_eq!(label,"energy-empty");assert_eq!(store.snapshot().unwrap(),NoConfig{});let projected:serde_json::Value=(&semio_framework_value::ToValue::to_value(&NoConfig{})).into();assert_eq!(projected,law["state"]);let canonical=<NoConfig as store::snapshot::ArtifactPack>::encode_pack_with(&NoConfig{},&Default::default()).unwrap();assert!(!canonical.is_empty());assert_eq!(store.envelope().vcs.genesis.pack(),canonical);assert!(<NoConfig as store::snapshot::ArtifactPack>::decode_pack_with(&[],&Default::default()).is_err());assert_eq!(<NoConfig as store::snapshot::ArtifactPack>::decode_pack_with(&canonical,&Default::default()).unwrap(),NoConfig{});assert_eq!(store.envelope().schema,O::SCHEMA);}else{caller.cancel().cancel_now()}
  for index in 0..1000000{if owner.as_ref().unwrap().terminal_is_empty(){break}original_emission_capture_tests::actual_turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|owner.as_mut().unwrap().close_step(cx)));assert!(index<999999,"empty native genesis close stalled")}
  original_emission_capture_tests::actual_turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=OriginalStoreGenesis::<O>::boxed_release_demands();close_original_retained_step(cx,d,|_|{owner.take();Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));
  if let Some((_label,mut store))=candidate{for index in 0..1000000{if store.close_owned_store_terminal_is_empty(){break}original_emission_capture_tests::actual_turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|g|store.close_owned_store_step(g))?;Ok(())}));assert!(index<999999,"empty native Store close stalled")}original_emission_capture_tests::actual_turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=RetirementDemand{release_bytes:size_of_val(&*store),depth:1,..Default::default()};close_original_retained_step(cx,d,|_|{drop(store);Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));}
  while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}caller.retire(g);
 }
}
#[test]fn original_empty_config_genesis_retains_canonical_record_and_every_cancel_prefix(){empty_genesis::<NoConfigGenesisOwner>()}
#[test]fn original_empty_draft_genesis_retains_canonical_record_and_every_cancel_prefix(){empty_genesis::<NoDraftGenesisOwner>()}
